//
// Each entry was resolved by matching the English verse text in
// daily_verses.js against bible_verses, so psalm references land on the
// right Vulgate chapter rather than on the Hebrew number.

const DAILY_VERSES_ES = {
  1: [
    { text: "Porque yo sé los designios que tengo sobre vosotros, dice el Señor, designios de paz, y no de aflicción, para daros la libertad que es el objeto de vuestra expectación.", ref: "Jeremías 29:11" },
    { text: "Pero Jesús, mirándolos blandamente, les dijo: Para los hombres es esto imposible, que para Dios todas las cosas posibles.", ref: "Mateo 19:26" },
    { text: "Pedid, y se os dará; ¡buscad, y hallaréis!: llamad, y os abrirán.", ref: "Mateo 7:7" },
    { text: "Todo lo puedo en aquel que me conforta, esto es, en Cristo.", ref: "Filipenses 4:13" },
    { text: "Mira que yo soy el que te lo mando", ref: "Josué 1:9" },
    { text: "El Señor es mi pastor, nada me faltará.", ref: "Salmos 22:1" },
    { text: "Arroja en el seno del Señor tus ansiedades, y él te sustentará; no dejará al justo en agitación perpetua.", ref: "Salmos 54:22" },
    { text: "En el principio creó Dios el cielo y la tierra.", ref: "Génesis 1:1" },
    { text: "El Señor es mi luz y mi salvación: ¿a quién he de temer yo? El Señor es el defensor de mi vida: ¿quién me hará temblar?", ref: "Salmos 26:1" },
    { text: "No temas, digo, que yo estoy contigo; no te desvíes, pues yo soy tu Dios; yo te he confortado, y te he auxiliado, y la diestra poderosa de mi Justo te ha amparado.", ref: "Isaías 41:10" },
    { text: "Estas cosas os he dicho con el fin de que halléis en mí la paz. En el mundo tendréis grandes tribulaciones, pero tened confianza, yo he vencido al mundo.", ref: "Juan 16:33" },
    { text: "Bienaventurados los pobres de espíritu, porque de ellos es el reino de los cielos.", ref: "Mateo 5:3" },
    { text: "Venid a mí todos los que andáis agobiados con trabajos y cargas, que yo os aliviaré.", ref: "Mateo 11:28" },
    { text: "Nosotros así mismo hemos conocido y creído el amor que nos tiene Dios. Dios es caridad, o amor; y el que permanece en la caridad, en Dios permanece, y Dios en él.", ref: "1 Juan 4:16" },
    { text: "El Señor dará fortaleza a su pueblo. El Señor colmará a su pueblo de bendiciones de paz.", ref: "Salmos 28:11" },
    { text: "Cuando he aquí que le presentaron un paralítico postrado en un lecho. Y al ver Jesús su fe, dijo al tullido: Ten confianza, hijo mío, que perdonados te son tus pecados.", ref: "Mateo 9:2" },
    { text: "y me respondió: Bástate mi gracia, porque el poder mío brilla y consigue su fin por medio de la flaqueza. Así que con gusto me gloriaré de mis flaquezas o enfermedades, para que haga morada en mí el poder de Cristo.", ref: "2 Corintios 12:9" },
    { text: "Así que buscad primero el reino de Dios y su justicia, y todas las demás cosas se os darán por añadidura.", ref: "Mateo 6:33" },
    { text: "No te dejes vencer del mal, o del deseo de venganza, mas procura vencer al mal con el bien, o a fuerza de beneficios.", ref: "Romanos 12:21" },
    { text: "Mas el que perseverare hasta el fin, ése se salvará.", ref: "Mateo 24:13" },
    { text: "Y conoceréis la verdad, y la verdad os hará libres.", ref: "Juan 8:32" },
    { text: "Le respondió Jesús: Yo soy el camino, la verdad, y la vida: Nadie viene al Padre sino por mí.", ref: "Juan 14:6" },
    { text: "porque dentro de él vivimos, nos movemos, y existimos; y como algunos de vuestros poetas dijeron: Somos del linaje, o descendencia, del mismo Dios.", ref: "Hechos 17:28" },
    { text: "Después de esto, ¿qué diremos ahora? Si Dios está con nosotros, ¿quién contra nosotros?", ref: "Romanos 8:31" },
    { text: "Mas Jesús, oyendo lo que decían dijo al jefe de la sinagoga: No temas, ten fe solamente.", ref: "Marcos 5:36" },
    { text: "Pronto está el Señor para todos los que le invocan, para cuantos le invocan de veras.", ref: "Salmos 144:18" },
    { text: "Renovaos, pues, ahora en el espíritu de vuestra mente o interior de vuestra alma.", ref: "Efesios 4:23" },
    { text: "Antorcha para mis pies es tu palabra Juré, y ratifiqué el observar tus justísimos decretos.", ref: "Salmos 118:105-106" },
    { text: "El Señor te guardará en todos los pasos de tu vida, desde ahora y para siempre.", ref: "Salmos 120:8" },
    { text: "Todas las cosas que hizo Dios son buenas, usadas a su tiempo; y el Señor entregó al mundo a las vanas disputas de los hombres; de suerte que ninguno de ellos puede entender perfectamente las obras que Dios creó desde el principio hasta el fin.", ref: "Eclesiastés 3:11" },
    { text: "Y no queráis conformaros con este siglo, antes bien transformaos con la renovación de vuestro espíritu; a fin de acertar qué es lo bueno, y lo más agradable, y lo perfecto que Dios quiere de vosotros.", ref: "Romanos 12:2" },
  ],
  2: [
    { text: "El precepto mio es, que os ameis unos pa otros, como yo os he amado á vosotros.", ref: "Juan 15:12" },
    { text: "Que amó tanto Dios al mundo, que no paró hasta dar a su hijo unigénito; a fin de que todos los que creen en él, no perezcan, sino que vivan vida eterna.", ref: "Juan 3:16" },
    { text: "Al contrario, los frutos del espíritu son caridad, gozo, paz, paciencia, benignidad, bondad, longanimidad,", ref: "Gálatas 5:22" },
    { text: "Que nadie tiene amor más grande que el que da su vida por sus amigos.", ref: "Juan 15:13" },
    { text: "Amemos, pues, a Dios, ya que Dios nos amó el primero.", ref: "1 Juan 4:19" },
    { text: "Pero sobre todo mantened constante la mutua caridad entre vosotros", ref: "1 Pedro 4:8" },
    { text: "Ahora bien, a vosotros que me escucháis, digo yo: Amad a vuestros enemigos; haced bien a los que os aborrecen.", ref: "Lucas 6:27" },
    { text: "Al contrario, sed mutuamente afables, compasivos, perdonándoos los unos a los otros, así como también Dios os ha perdonado a vosotros por Cristo.", ref: "Efesios 4:32" },
    { text: "El amor nunca se acaba; las profecías se terminarán, y cesarán las lenguas, y se acabará la ciencia.", ref: "1 Corintios 13:8" },
    { text: "Pero sobre todo mantened la caridad, la cual es el vínculo de la perfección.", ref: "Colosenses 3:14" },
    { text: "Quien no tiene este amor, no conoce a Dios, puesto que Dios es todo caridad, o amor.", ref: "1 Juan 4:8" },
    { text: "Respondióle Jesús: Amarás al Señor Dios tuyo de todo tu corazón, y con toda tu alma, y con toda tu mente:", ref: "Mateo 22:37" },
    { text: "El segundo es semejante a éste, y es: Amarás a tu prójimo como a ti mismo.", ref: "Mateo 22:39" },
    { text: "Por aquí conocerán todos que sois mis discípulos, si os tenéis amor unos a otros.", ref: "Juan 13:35" },
    { text: "El amor es paciente, es dulce y bienhechor; el amor no tiene envidia, no obra precipitada ni temerariamente, no se ensoberbece,", ref: "1 Corintios 13:4" },
    { text: "Ahora permanecen estas tres virtudes: la fe, la esperanza y el amor; pero de las tres el amor es la más excelente de todas.", ref: "1 Corintios 13:13" },
    { text: "Todas vuestras cosas háganse con caridad.", ref: "1 Corintios 16:14" },
    { text: "y proceded con amor hacia vuestros hermanos, a ejemplo de lo que Cristo nos amó, y se ofreció a sí mismo a Dios en oblación y hostia de olor suavísimo.", ref: "Efesios 5:2" },
    { text: "Sed, pues, misericordiosos, así como también vuestro padre es misericordioso.", ref: "Lucas 6:36" },
    { text: "No juzguéis, y no seréis juzgados; no condenéis, y no seréis condenados. Perdonad, y seréis perdonados.", ref: "Lucas 6:37" },
    { text: "Benigno es el Señor, exclamarán, y misericordioso, paciente y clemente.", ref: "Salmos 144:8" },
    { text: "Alabad al Señor, porque es infinitamente bueno, porque es eterna su misericordia.", ref: "Salmos 135:1" },
    { text: "Es verdad que me visitó el Señor, responde Israel, mas hace ya mucho tiempo. Te engañas, dice Dios, porque yo te he amado con perpetuo y no interrumpido amor; por eso, misericordioso, te atraje a mí.", ref: "Jeremías 31:3" },
    { text: "Vosotros, hijitos míos, de Dios sois, y habéis vencido a aquél, porque el que está con vosotros y os ayuda con su gracia, es mayor que el espíritu del Anticristo que está en el mundo.", ref: "1 Juan 4:4" },
    { text: "No os dejaré huérfanos: yo volveré a vosotros.", ref: "Juan 14:18" },
    { text: "Al modo que mi Padre me amó, así os he amado yo. Perseverad en mi amor.", ref: "Juan 15:9" },
    { text: "Bienaventurados los misericordiosos, porque ellos alcanzarán misericordia.", ref: "Mateo 5:7" },
    { text: "Comportad las cargas unos de otros, y con eso cumpliréis la ley de Cristo.", ref: "Gálatas 6:2" },
    { text: "Carísimos, amémonos los unos a los otros, porque la caridad procede de Dios. Y todo aquel que así ama, es hijo de Dios, y conoce a Dios.", ref: "1 Juan 4:7" },
  ],
  3: [
    { text: "A lo que Pedro les respondió: Haced penitencia, y sea bautizado cada uno de vosotros en el nombre de Jesucristo para remisión de vuestros pecados; y recibiréis el don del Espíritu Santo;", ref: "Hechos 2:38" },
    { text: "Y entonces venid y argüidme, dice el Señor: Aunque vuestros pecados os hayan teñido como la grana, quedarán vuestras almas blancas como la nieve; y aunque fuesen teñidas de encarnado como el rojo, se volverán del color de la lana más blanca.", ref: "Isaías 1:18" },
    { text: "No son los justos, sino los pecadores a los que he venido yo a llamar a penitencia.", ref: "Lucas 5:32" },
    { text: "El espíritu compungido es el sacrificio más grato para Dios; no despreciarás, ¡oh Dios mío!, el corazón contrito y humillado.", ref: "Salmos 50:17" },
    { text: "Ahora, pues, convertíos a mí, dice el Señor, de todo vuestro corazón, con ayunos, con lágrimas, y con gemidos.", ref: "Joel 2:12" },
    { text: "Aunque desde los tiempos de vuestros padres os apartasteis de mis leyes, y no las observasteis. Volveos ya a mí, y yo me volveré a vosotros, dice el Señor de los ejércitos. Pero vosotros decís: ¿Qué es lo que haremos para convertirnos a ti?", ref: "Malaquías 3:7" },
    { text: "Pero si confesamos humildemente nuestros pecados, fiel y justo es él para perdonárnoslos y lavarnos de toda iniquidad, según su promesa.", ref: "1 Juan 1:9" },
    { text: "El Señor está al lado de los que tienen el corazón atribulado", ref: "Salmos 33:18" },
    { text: "Crea en mí, ¡oh Dios!, un corazón puro, y renueva en mis entrañas el espíritu de rectitud.", ref: "Salmos 50:10" },
    { text: "Os digo que de este modo habrá más fiesta en el cielo por un pecador que se arrepiente, que por noventa y nueve justos, que no tienen necesidad de penitencia.", ref: "Lucas 15:7" },
    { text: "Que amó tanto Dios al mundo, que no paró hasta dar a su hijo unigénito; a fin de que todos los que creen en él, no perezcan, sino que vivan vida eterna.", ref: "Juan 3:16" },
    { text: "Bienaventurados los que lloran porque ellos serán consolados.", ref: "Mateo 5:5" },
    { text: "Por tanto, yo juzgaré, dice el Señor Dios, ¡oh casa de Israel!, a cada cual según sus obras. Convertíos y haced penitencia de todas vuestras maldades; y no serán éstas causa de vuestra perdición.", ref: "Ezequiel 18:30" },
    { text: "No, yo iré a mi padre y le diré: Padre mío, pequé contra el cielo, y contra ti;", ref: "Lucas 15:18" },
    { text: "Aparta tu rostro de mis pecados, y borra todas mis iniquidades.", ref: "Salmos 50:9" },
    { text: "Allegaos a Dios, y él se allegará a vosotros. Limpiad, ¡oh pecadores!, vuestras manos; y vosotros de ánimo doble, purificad vuestros corazones.", ref: "Santiago 4:8" },
    { text: "Mas de ti, ¡oh Señor Dios nuestro!, es propia la misericordia y la clemencia para con los pecadores; porque nosotros nos hemos apartado de ti,", ref: "Daniel 9:9" },
    { text: "Desde lo más profundo clamé a ti, ¡oh Señor!", ref: "Salmos 129:1" },
    { text: "Quien encubre sus pecados no podrá ser dirigido; mas el que los confesare y se arrepintiere de ellos, alcanzará misericordia.", ref: "Proverbios 28:13" },
    { text: "Bendice, ¡oh alma mía!, al Señor, y bendigan todas mis entrañas su santo Nombre.", ref: "Salmos 102:1" },
    { text: "Y rasgad vuestros corazones, y no vuestros vestidos; y convertíos al Señor Dios vuestro, puesto que el Señor es benigno y misericordioso, y paciente, y de mucha clemencia, e inclinado a suspender el castigo.", ref: "Joel 2:13" },
    { text: "pues yo les perdonaré sus maldades, y no me acordaré más de sus pecados.", ref: "Hebreos 8:12" },
    { text: "Haced dignos frutos de penitencia, y no andéis diciendo: Tenemos a Abrahán por padre. Porque yo os digo que de estas piedras puede hacer Dios nacer hijos de Abrahán.", ref: "Lucas 3:8" },
    { text: "Mortificaos, entristeceos y sollozad; cámbiese, vuestra risa en llanto, y el gozo en tristeza.", ref: "Santiago 4:9" },
    { text: "¿Quién dará agua a mi cabeza, y hará de mis ojos dos fuentes de lágrimas para llorar día y noche la muerte que se ha dado a tantos moradores de la hija de mi pueblo, o de Jerusalén ?", ref: "Jeremías 9:1" },
    { text: "Yo curaré sus llagas, responde el Señor, los amaré por pura gracia; por cuanto se ha aplacado mi indignación contra ellos.", ref: "Oseas 14:4" },
    { text: "¡Oh Señor!, tú eres mi Dios, y a ti tributaré acciones de gracias; tú eres mi Dios, y tu gloria ensalzaré. Tus alabanzas cantaré, porque me has oído, y te hiciste mi salvador.", ref: "Salmos 117:28" },
    { text: "No retarda, pues, el Señor su promesa, como algunos juzgan, sino que espera con mucha paciencia por amor de vosotros venir como juez, no queriendo que ninguno perezca, sino que todos se conviertan a penitencia.", ref: "2 Pedro 3:9" },
    { text: "Está en medio de ti el Señor, el Dios tuyo, el fuerte; él te salvará; en ti hallará él su gozo y su alegría, será constante en amarte, se regocijará, y celebrará tus alabanzas.", ref: "Sofonías 3:17" },
    { text: "Te manifesté mi delito, y dejé de ocultar mi injusticia. Confesaré, dije yo, contra mí mismo al Señor la injusticia mía, y tú perdonaste la malicia de mi pecado.", ref: "Salmos 31:5" },
    { text: "Compasivo es el Señor y benigno, tardo en airarse y de gran clemencia.", ref: "Salmos 102:8" },
  ],
  4: [
    { text: "ya no está aquí porque ha resucitado, según predijo. Venid y mirad el lugar donde estaba sepultado el Señor.", ref: "Mateo 28:6" },
    { text: "Le dijo Jesús: Yo soy la resurrección y la vida: Quien cree en mí, aunque hubiere muerto, vivirá;", ref: "Juan 11:25" },
    { text: "Este es el día que ha hecho el Señor. Alegrémonos y recocijémonos en él.", ref: "Salmos 117:24" },
    { text: "Mas cuando este cuerpo mortal haya sido revestido de inmortalidad, entonces se cumplirá la palabra escrita: La muerte ha sido absorbida por una victoria.", ref: "1 Corintios 15:54" },
    { text: "Ahora bien, si habéis resucitado con Cristo, buscad las cosas que son de arriba, donde Cristo está sentado a la diestra de Dios Padre;", ref: "Colosenses 3:1" },
    { text: "que decían: El Señor ha resucitado realmente, y se ha aparecido a Simón.", ref: "Lucas 24:34" },
    { text: "El cual les repitió: La paz sea con vosotros. Como mi Padre me envió, así os envío también a vosotros.", ref: "Juan 20:21" },
    { text: "y yo vivo ahora, o más bien no soy yo el que vivo, sino que Cristo vive en mí. Así la vida que vivo ahora en esta carne, la vivo en la fe del Hijo de Dios, el cual me amó, y se entregó a sí mismo a la muerte por mí.", ref: "Gálatas 2:20" },
    { text: "Vivid siempre alegres en el Señor; vivid alegres, repito.", ref: "Filipenses 4:4" },
    { text: "Y quedando llenas de espanto, y teniendo inclinado el rostro hacia la tierra, los ángeles les dijeron: ¿Para qué andáis buscando entre los muertos al que está vivo?", ref: "Lucas 24:5" },
    { text: "Pero Dios le resucitó al tercer día, y dispuso que se dejase ver,", ref: "Hechos 10:40" },
    { text: "sabiendo que Cristo resucitado de entre los muertos no muere ya otra vez", ref: "Romanos 6:9" },
    { text: "Pero demos gracias a Dios, que nos ha dado victoria contra la muerte y el pecado, por virtud de nuestro Señor Jesucristo.", ref: "1 Corintios 15:57" },
    { text: "Y si Cristo no resucitó, vana es vuestra fe, pues todavía estáis en vuestros pecados.", ref: "1 Corintios 15:17" },
    { text: "Bendito sea el Dios y Padre de Nuestro Señor Jesucristo, que por su gran misericordia nos ha regenerado con una viva esperanza de vida eterna, mediante la resurrección de Jesucristo de entre los muertos,", ref: "1 Pedro 1:3" },
    { text: "El Señor es mi fortaleza y mi gloria", ref: "Salmos 117:14" },
    { text: "servid al Señor con alegría. Venid llenos de alborozo a presentaros ante su acatamiento.", ref: "Salmos 99:2" },
    { text: "Saltó de gozo en el Señor, mi corazón, y mi Dios me ha ensalzado; ya puedo responder a boca llena a mis enemigos, pues toda la causa de mi alegría es, ¡oh Señor!,la salud que he recibido de ti.", ref: "1 Samuel 2:1" },
    { text: "Moradores todos de la tierra, dirigid a Dios voces de júbilo.", ref: "Salmos 65:1" },
    { text: "No me moriré, sino que viviré aún, y publicaré las obras del Señor.", ref: "Salmos 117:17" },
    { text: "Fue, pues, María Magdalena a dar parte a los discípulos, diciendo: He visto al Señor, y me ha dicho esto.", ref: "Juan 20:18" },
    { text: "Le dijo Jesús: No me toques más, porque no he subido todavía a mi Padre; mas anda, ve a mis hermanos, y diles de mi parte: Subo a mi Padre y vuestro Padre; a mi Dios y vuestro Dios.", ref: "Juan 20:17" },
    { text: "Le dijo Jesús: Tú has creído, ¡oh Tomás!, porque me has visto: bienaventurados aquellos que sin haberme visto han creído.", ref: "Juan 20:29" },
    { text: "Que así como en Adán mueren todos, así en Cristo todos serán vivificados.", ref: "1 Corintios 15:22" },
    { text: "Por lo cual estoy seguro de que ni la muerte, ni la vida, ni los ángeles, ni los principados, ni las virtudes, ni lo presente, ni lo venidero, ni la fuerza, o violencia,", ref: "Romanos 8:38" },
    { text: "Sí, cosas grandes ha obrado el Señor a favor nuestro, inundados estamos de gozo.", ref: "Salmos 125:3" },
    { text: "Alabad al Señor, naciones todas de la tierra, pueblos todos cantad sus alabanzas.", ref: "Salmos 116:1" },
    { text: "¿Dónde está, ¡oh muerte!, tu victoria? ¿Dónde está, ¡oh muerte!, tu aguijón?", ref: "1 Corintios 15:55" },
    { text: "En la casa de mi Padre hay muchas habitaciones; que si no fuese así, os lo hubiera yo dicho. Yo voy a preparar lugar para vosotros.", ref: "Juan 14:2" },
    { text: "Así vosotros ahora a la verdad padecéis tristeza; pero yo volveré a visitaros, y vuestro corazón se bañará en gozo, y nadie os quitará vuestro gozo.", ref: "Juan 16:22" },
  ],
  5: [
    { text: "Y habiendo entrado el ángel a donde ella estaba, le dijo: Dios te salve, ¡oh llena de gracia!, el Señor es contigo; bendita tú eres entre todas las mujeres.", ref: "Lucas 1:28" },
    { text: "y exclamando en voz alta, dijo: ¡Bendita tú eres entre todas las mujeres, y bendito es el fruto de tu vientre!", ref: "Lucas 1:42" },
    { text: "Entonces María dijo: Mi alma glorifica al Señor,", ref: "Lucas 1:46" },
    { text: "Porque ha hecho en mí cosas grandes aquel que es todopoderoso, cuyo nombre es santo,", ref: "Lucas 1:49" },
    { text: "porque ha puesto los ojos en la bajeza de su esclava; por tanto ya desde ahora me llamarán bienaventurada todas las generaciones.", ref: "Lucas 1:48" },
    { text: "Entonces dijo María: He aquí la esclava del Señor, hágase en mí según tu palabra. Y en seguida el ángel desapareciendo se retiró de su presencia.", ref: "Lucas 1:38" },
    { text: "Y como viniese a faltar el vino, dijo a Jesús su madre: No tienen vino.", ref: "Juan 2:3" },
    { text: "Dijo entonces su madre a los sirvientes: Haced lo que él os diga.", ref: "Juan 2:5" },
    { text: "Habiendo mirado, pues, Jesús a su madre y al discípulo que él amaba, el cual estaba allí, dice a su madre: Mujer, ahí tienes a tu hijo.", ref: "Juan 19:26" },
    { text: "En esto apareció un gran prodigio en el cielo, una mujer vestida del sol, y la luna debajo de sus pies, y en su cabeza una corona de doce estrellas.", ref: "Apocalipsis 12:1" },
    { text: "Y el Verbo se hizo carne; y habitó en medio de nosotros; y nosotros hemos visto su gloria, gloria que el Unigénito debía recibir del Padre, lleno de gracia y de verdad.", ref: "Juan 1:14" },
    { text: "Estando diciendo estas cosas, he aquí que una mujer, levantando la voz de en medio del pueblo, exclamó: Bienaventurado el vientre que te llevó, y los pechos que te alimentaron.", ref: "Lucas 11:27" },
    { text: "y cuya misericordia se derrama de generación en generación sobre los que le temen.", ref: "Lucas 1:50" },
    { text: "Mas el ángel le dijo: ¡Oh María!, no temas, porque has hallado gracia en los ojos de Dios.", ref: "Lucas 1:30" },
    { text: "El ángel en respuesta le dijo: El Espíritu Santo descenderá sobre ti, y la virtud del Altísimo te cubrirá con su sombra, por esta causa el fruto santo que de ti nacerá será llamado Hijo de Dios.", ref: "Lucas 1:35" },
    { text: "Derribó del solio a los poderosos, y ensalzó a los humildes.", ref: "Lucas 1:52" },
    { text: "Colmó de bienes a los hambrientos, y a los ricos los despidió sin nada.", ref: "Lucas 1:53" },
    { text: "Acordándose de su misericordia, acogió a Israel su siervo,", ref: "Lucas 1:54" },
    { text: "y mi espíritu está transportado de gozo en el Dios salvador mío:", ref: "Lucas 1:47" },
    { text: "Y tuvo a su hijo primogénito, y lo envolvió en pañales, y lo recostó en un pesebre, porque no hubo lugar para ellos en el mesón.", ref: "Lucas 2:7" },
    { text: "María conservaba todas estas cosas dentro de sí, ponderándolas en su corazón.", ref: "Lucas 2:19" },
    { text: "lo que será para ti misma una espada que traspasará tu alma", ref: "Lucas 2:35" },
    { text: "Y él les respondió: ¿Cómo es que me buscabas? ¿No sabíais que yo debo emplearme en las cosas que miran al servicio de mi Padre?", ref: "Lucas 2:49" },
    { text: "Por aquellos días partió María, y se fue apresuradamente a las montañas de Judea a una ciudad de la tribu de Judá;", ref: "Lucas 1:39" },
    { text: "Estaban al mismo tiempo junto a la cruz de Jesús su madre, y la hermana, o parienta de su madre, María, mujer de Cleofás, y María Magdalena.", ref: "Juan 19:25" },
    { text: "En seguida se fue con ellos, y vino a Nazaret, y les estaba sujeto. Y su madre conservaba todas estas cosas en su corazón.", ref: "Lucas 2:51" },
    { text: "Pero Jesús respondió: Bienaventurados más bien los que escuchan la palabra de Dios, y la ponen en práctica.", ref: "Lucas 11:28" },
    { text: "Hizo alarde del poder de su brazo Derribó del solio a los poderosos, y ensalzó a los humildes.", ref: "Lucas 1:51-52" },
    { text: "Este será grande, y será llamado Hijo del Altísimo, al cual el Señor Dios dará el trono de su padre David, y reinará en la casa de Jacob eternamente,", ref: "Lucas 1:32" },
    { text: "¡Oh bienaventurada tú que has creído! Porque se cumplirán las cosas que se te han dicho de parte del Señor.", ref: "Lucas 1:45" },
    { text: "Lo mismo fue oír el saludo de María, que la criatura, diera saltos de placer en su vientre, e Isabel se sintió llena del Espíritu Santo,", ref: "Lucas 1:41" },
  ],
  6: [
    { text: "Tomad mi yugo sobre vosotros, y aprended de mí, que soy manso y humilde de corazón; y hallaréis el reposo para vuestras almas.", ref: "Mateo 11:29" },
    { text: "Porque suave es mi yugo y ligero el peso mío.", ref: "Mateo 11:30" },
    { text: "Yo soy el pan vivo, que he descendido del cielo. Quien comiere de este pan, vivirá eternamente; y el pan que yo daré, es mi misma carne, la cual daré yo para la vida o salvación del mundo.", ref: "Juan 6:51" },
    { text: "Que nadie tiene amor más grande que el que da su vida por sus amigos.", ref: "Juan 15:13" },
    { text: "Que amó tanto Dios al mundo, que no paró hasta dar a su hijo unigénito; a fin de que todos los que creen en él, no perezcan, sino que vivan vida eterna.", ref: "Juan 3:16" },
    { text: "Al modo que mi Padre me amó, así os he amado yo. Perseverad en mi amor.", ref: "Juan 15:9" },
    { text: "Yo soy el buen pastor. El buen pastor sacrifica su vida por sus ovejas.", ref: "Juan 10:11" },
    { text: "A lo que Jesús respondió: Yo soy el pan de vida; el que viene a mí, no tendrá hambre, y el que cree en mí, no tendrá sed jamás.", ref: "Juan 6:35" },
    { text: "Y volviendo Jesús a hablar al pueblo, dijo: Yo soy la luz del mundo. El que me sigue, no camina a oscuras, sino que tendrá la luz de la vida.", ref: "Juan 8:12" },
    { text: "Yo soy la puerta. El que por mí entrare, se salvará; y entrará, y saldrá sin tropiezo, y hallará pastos.", ref: "Juan 10:9" },
    { text: "Porque el Hijo del hombre ha venido a buscar y a salvar lo que había perecido.", ref: "Lucas 19:10" },
    { text: "He aquí que estoy a la puerta de tu corazón, y llamo; si alguno escuchare mi voz y me abriere la puerta, entraré a él, y con él cenaré, y él conmigo.", ref: "Apocalipsis 3:20" },
    { text: "En el último día de la fiesta, que es el más solemne, Jesús se puso en pie, y en alta voz decía: Si alguno tiene sed, venga a mí, y beba.", ref: "Juan 7:37" },
    { text: "Yo soy la vid, vosotros los sarmientos; quien está unido, pues, conmigo y yo con él, ese da mucho fruto, porque sin mí nada podéis hacer.", ref: "Juan 15:5" },
    { text: "Ya no os llamaré siervos", ref: "Juan 15:15" },
    { text: "El ladrón no viene sino para robar, y matar, y hacer estrago. Mas yo he venido para que las ovejas tengan vida, y la tengan en más abundancia.", ref: "Juan 10:10" },
    { text: "Quien ha recibido mis mandamientos, y los observa, ése es el que me ama. Y el que me ama, será amado de mi Padre; y yo le amaré, y yo mismo me manifestaré a él.", ref: "Juan 14:21" },
    { text: "Esas cosas os he dicho, a fin de que observándolas fielmente os gocéis con el gozo mío, y vuestro gozo sea completo.", ref: "Juan 15:11" },
    { text: "Mi Padre queda glorificado en que vosotros llevéis mucho fruto, y seáis verdaderos discípulos míos.", ref: "Juan 15:8" },
    { text: "Jesús le responde: Tanto tiempo hace que estoy con vosotros, ¿y aún no me habéis conocido? Felipe, quien me ve a mí, ve también al Padre. ¿Pues cómo dices tú: Muéstranos al Padre?", ref: "Juan 14:9" },
    { text: "Permaneced en mí, que yo permaneceré en vosotros. Al modo que el sarmiento no puede de suyo producir, si no está unido con la vid, así tampoco vosotros si no estáis unidos conmigo.", ref: "Juan 15:4" },
    { text: "No me elegisteis vosotros a mí, si no que yo soy el que os he elegido, y destinado para que vayáis por todo el mundo y hagáis fruto, y vuestro fruto sea duradero, a fin de que cualquier cosa que pidiereis al Padre en mi nombre, os la conceda.", ref: "Juan 15:16" },
    { text: "Hasta ahora nada le habéis pedido en mi nombre: Pedidle, y recibiréis, para que vuestro gozo sea completo.", ref: "Juan 16:24" },
    { text: "Estas cosas os he dicho con el fin de que halléis en mí la paz. En el mundo tendréis grandes tribulaciones, pero tened confianza, yo he vencido al mundo.", ref: "Juan 16:33" },
    { text: "¡Oh Padre!, yo deseo ardientemente que aquellos que tú me has dado, estén conmigo allí mismo donde yo estoy para que contemplen mi gloria, cual tú me la has dado; porque tú me amaste desde antes de la creación del mundo.", ref: "Juan 17:24" },
    { text: "Tomando la palabra Simón Pedro, dijo: Tú eres el Cristo, o Mesías, el Hijo del Dios vivo.", ref: "Mateo 16:16" },
    { text: "y de parte de Jesucristo, el cual es testigo fiel, primogénito, o el primero que resucitó de entre los muertos, y soberano de los reyes de la tierra, el cual nos amó, y nos lavó de nuestros pecados con su sangre,", ref: "Apocalipsis 1:5" },
    { text: "Y en esto consiste su caridad; que no es porque nosotros hayamos amado a Dios, sino que él nos amó primero a nosotros, y envió a su Hijo a ser víctima de propiciación por nuestros pecados.", ref: "1 Juan 4:10" },
    { text: "ni todo lo que hay de más alto, ni de más profundo, ni otra ninguna criatura podrá jamás separarnos del amor de Dios, que se funda en Jesucristo nuestro Señor.", ref: "Romanos 8:39" },
    { text: "esperanza que no burla; porque la caridad de Dios ha sido derramada en nuestros corazones por medio del Espíritu Santo, que se nos ha dado.", ref: "Romanos 5:5" },
  ],
  7: [
    { text: "El Señor es mi pastor, nada me faltará.", ref: "Salmos 22:1" },
    { text: "Confía en el Señor con todo tu corazón, y no te apoyes en tu prudencia.", ref: "Proverbios 3:5" },
    { text: "En todas tus empresas tenle presente, y él sea quien dirija todos tus pasos.", ref: "Proverbios 3:6" },
    { text: "descargando en su amoroso seno todas vuestras solicitudes, pues él tiene cuidado de vosotros.", ref: "1 Pedro 5:7" },
    { text: "El Señor es el que me auxilia y protege; en él esperó mi corazón, y fui socorrido. Y resucitó mi carne; y así le alabaré con todo mi afecto.", ref: "Salmos 27:7" },
    { text: "Expón al Señor tu situación, y confía en él; y él obrará.", ref: "Salmos 36:5" },
    { text: "Así que no vayáis diciendo acongojados: ¿Dónde hallaremos qué comer y beber? ¿Dónde hallaremos con qué vestirnos?,", ref: "Mateo 6:31" },
    { text: "como hacen los paganos, los cuales andan ansiosos tras todas estas cosas; que bien sabe vuestro Padre la necesidad que de ellas tenéis.", ref: "Mateo 6:32" },
    { text: "Así que buscad primero el reino de Dios y su justicia, y todas las demás cosas se os darán por añadidura.", ref: "Mateo 6:33" },
    { text: "Pues qué ¿hay para Dios cosa difícil? Al plazo prometido volveré a visitarte por este mismo tiempo, si Dios quiere, y Sara tendrá un hijo.", ref: "Génesis 18:14" },
    { text: "Por este motivo padezco lo que padezco, pero no me avergüenzo. Porque bien sé de quién me he fiado, y estoy cierto de que es poderoso para conservar mi depósito hasta aquel último día.", ref: "2 Timoteo 1:12" },
    { text: "Yo soy el Señor Dios tuyo, que te ha sacado de la tierra de Egipto, de la casa de la esclavitud.", ref: "Éxodo 20:2" },
    { text: "Arriba en lo más alto de los cielos está su morada y llegan acá abajo sus brazos o poder eterno. Arrojará de tu presencia al enemigo, y le dirá: Quédate reducido a polvo.", ref: "Deuteronomio 33:27" },
    { text: "El que se acoge al asilo del Altísimo, descansará siempre bajo la protección del Dios del cielo.", ref: "Salmos 90:1" },
    { text: "Sean las costumbres sin rastro de avaricia, contentándoos con lo presente, pues el mismo Dios dice: No te desampararé, ni abandonaré jamás;", ref: "Hebreos 13:5" },
    { text: "de manera que podamos animosamente decir: El Señor es quien me ayuda", ref: "Hebreos 13:6" },
    { text: "Sabemos también nosotros que todas las cosas contribuyen al bien de los que aman a Dios, de aquellos, digo, que él ha llamado según su decreto para ser santos.", ref: "Romanos 8:28" },
    { text: "Porque yo sé los designios que tengo sobre vosotros, dice el Señor, designios de paz, y no de aflicción, para daros la libertad que es el objeto de vuestra expectación.", ref: "Jeremías 29:11" },
    { text: "El Señor peleará por vosotros, y vosotros os estaréis quedos.", ref: "Éxodo 14:14" },
    { text: "Confía en el Señor con todo tu corazón, y no te apoyes en tu prudencia.", ref: "Proverbios 3:5" },
    { text: "No temas, pues, porque yo estoy contigo; desde el oriente conduciré tus hijos ¡oh Jerusalén !, desde el occidente los congregaré.", ref: "Isaías 43:5" },
    { text: "Mi socorro viene del Señor que creó el cielo y la tierra.", ref: "Salmos 120:2" },
    { text: "Porque el Señor Dios, el Santo de Israel dice: Si os volviereis y os estuviereis quietos, seréis salvos; en la quietud y en la esperanza estará vuestra fortaleza. Mas vosotros no lo quisisteis hacer;", ref: "Isaías 30:15" },
    { text: "Dios es nuestro refugio y fortaleza, nuestro defensor en las tribulaciones que tanto nos han acosado.", ref: "Salmos 45:1" },
    { text: "Porque él mandó a sus ángeles que cuidasen de ti", ref: "Salmos 90:11" },
    { text: "Mirad las aves del cielo cómo no siembran, ni siegan, ni tienen graneros, y vuestro Padre celestial las alimenta. ¿Pues no valéis vosotros mucho más sin comparación que ellas?", ref: "Mateo 6:26" },
    { text: "Y ¿quién de vosotros a fuerza de discursos puede añadir un codo a su estatura?", ref: "Mateo 6:27" },
    { text: "Y acerca del vestido ¿con qué propósito inquietaros? Contemplad los lirios del campo cómo crecen y florecen. Ellos no labran, ni tampoco hilan;", ref: "Mateo 6:28" },
    { text: "Pues si una hierba del campo que hoy es, o florece, y mañana se echa en el horno, Dios así la viste, ¿cuánto más a vosotros, hombres de poca fe?", ref: "Mateo 6:30" },
    { text: "No se turbe vuestro corazón. Pues creéis en Dios, creed también en mí.", ref: "Juan 14:1" },
    { text: "Estas cosas os he dicho con el fin de que halléis en mí la paz. En el mundo tendréis grandes tribulaciones, pero tened confianza, yo he vencido al mundo.", ref: "Juan 16:33" },
  ],
  8: [
    { text: "El principio de la sabiduría es el temor del Señor", ref: "Proverbios 9:10" },
    { text: "Mas si alguno de vosotros tiene falta de sabiduría, pídasela a Dios, que a todos da copiosamente, y no hiere a nadie; y le será concedida.", ref: "Santiago 1:5" },
    { text: "Dichoso el hombre que ha adquirido la sabiduría, y es rico en prudencia;", ref: "Proverbios 3:13" },
    { text: "Más vale la sabiduría que las armas militares", ref: "Eclesiastés 9:18" },
    { text: "Al contrario, la sabiduría que desciende de arriba, además de ser honesta y llena de pudor, es pacífica, modesta, dócil, susceptible o concorde con todo lo bueno, llena de misericordia y de excelentes frutos de buenas obras, que no se mete a juzgar, y está ajena de hipocresía.", ref: "Santiago 3:17" },
    { text: "El hijo sabio es la alegría del padre Nada aprovecharán los tesoros mal habidos", ref: "Proverbios 10:1-2" },
    { text: "Quien anda con sabios, sabio será; el amigo de los necios se asemejará a ellos.", ref: "Proverbios 13:20" },
    { text: "Florecerá como la palma el varón justo, y descollará cual cedro del Líbano.", ref: "Salmos 91:12" },
    { text: "Más vale poquito con temor de Dios, que grandes riquezas, las cuales nunca sacian.", ref: "Proverbios 15:16" },
    { text: "A la caída precede la soberbia, y antes de la ruina se remonta el espíritu.", ref: "Proverbios 16:18" },
    { text: "Vale más el buen nombre que muchas riquezas. La buena reputación es más estimable que el oro y la plata.", ref: "Proverbios 22:1" },
    { text: "Dice el proverbio: La senda por la cual comenzó el joven a andar desde el principio, esa misma seguirá también cuando viejo.", ref: "Proverbios 22:6" },
    { text: "Y así el corazón de los sabios está contento en la casa donde hay tristeza, y el corazón de los necios donde hay diversión.", ref: "Eclesiastés 7:4" },
    { text: "Todo cuanto pudieres hacer de bueno, hazlo sin perder tiempo; puesto que ni obra, ni pensamiento, ni sabiduría, ni ciencia ha lugar en el sepulcro, hacia el cual vas corriendo.", ref: "Eclesiastés 9:10" },
    { text: "Todas las cosas tienen su tiempo, y todo lo que hay debajo del cielo pasa en el término que se le ha prescrito.", ref: "Eclesiastés 3:1" },
    { text: "Mejor, es pues, vivir dos juntos que uno solo; porque es ventajoso el estar en compañía.", ref: "Eclesiastés 4:9" },
    { text: "Al contrario, los frutos del espíritu son caridad, gozo, paz, paciencia, benignidad, bondad, longanimidad,", ref: "Gálatas 5:22" },
    { text: "Sea vuestra modestia patente a todos los hombres, el Señor está cerca.", ref: "Filipenses 4:5" },
    { text: "Por lo demás, hermanos míos, todo lo que es conforme a la verdad, todo lo que respira pureza, todo lo justo, todo lo que es santo, o santifica, todo lo que os haga amables, todo lo que sirve al buen nombre, toda virtud, toda disciplina loable, esto sea vuestro estudio.", ref: "Filipenses 4:8" },
    { text: "Haced, pues, todas las cosas sin murmuraciones ni perplejidades;", ref: "Filipenses 2:14" },
    { text: "Vosotros entre esos dones aspirad a los mejores. Yo voy, pues, a mostraros un camino o don todavía más excelente.", ref: "1 Corintios 12:31" },
    { text: "Pero hágase todo con decoro y con orden.", ref: "1 Corintios 14:40" },
    { text: "Acerca de las cosas o viandas sacrificadas a los ídolos, ya sabemos que todos nosotros tenemos bastante ciencia o conocimientos sobre eso. Mas la ciencia por sí sola hincha; la caridad es la que edifica.", ref: "1 Corintios 8:1" },
    { text: "Quien es fiel a lo poco, también lo es en lo mucho; y quien es injusto en lo poco, también lo es en lo mucho.", ref: "Lucas 16:10" },
    { text: "Un árbol bueno no puede dar frutos malos, ni un árbol malo darlos buenos.", ref: "Mateo 7:18" },
    { text: "Por sus frutos, pues, los podréis conocer.", ref: "Mateo 7:20" },
    { text: "Por tanto, cualquiera que escucha mis instrucciones y las practica, será semejante a un hombre cuerdo que fundó su casa sobre piedra;", ref: "Mateo 7:24" },
    { text: "Bienaventurados los que tienen puro su corazón, porque ellos verán a Dios.", ref: "Mateo 5:8" },
    { text: "Brille así vuestra luz ante los hombres, de manera que vean vuestras buenas obras y glorifiquen a vuestro Padre que está en los cielos.", ref: "Mateo 5:16" },
    { text: "Vosotros sois la sal de la tierra. Y si la sal se hace insípida, ¿con qué se le volverá el sabor? Para nada sirve ya, sino para ser arrojada y pisada de las gentes.", ref: "Mateo 5:13" },
    { text: "Antorcha de tu cuerpo son tus ojos: si tu ojo fuere puro, o estuviere limpio, todo tu cuerpo estará iluminado.", ref: "Mateo 6:22" },
  ],
  9: [
    { text: "Es, pues, la fe el fundamento o firme persuasión de las cosas que se esperan, y un convencimiento de las cosas que no se ven.", ref: "Hebreos 11:1" },
    { text: "Pues sin fe es imposible agradar a Dios; por cuanto el que se llega a Dios debe creer que Dios existe, y que es remunerador de los que le buscan.", ref: "Hebreos 11:6" },
    { text: "Y en la buena nueva es en donde se nos ha revelado la justicia que viene de Dios la cual nace de la fe, y se perfecciona en la fe, según aquello que está escrito: El justo vive por la fe.", ref: "Romanos 1:17" },
    { text: "En suma, como un cuerpo sin espíritu está muerto, así también la fe sin las obras está muerta.", ref: "Santiago 2:26" },
    { text: "A lo que Jesús le dijo: Si tú puedes creer, todo es posible para el que cree.", ref: "Marcos 9:23" },
    { text: "Les respondió Jesús: Porque tenéis poca fe. Pues ciertamente os aseguro que si tuviereis fe tan grande como un granito de mostaza, podréis decir a ese monte: Trasládate de aquí allá, y se trasladará; y nada os será imposible.", ref: "Mateo 17:19" },
    { text: "Pero pídala con fe sin sombra de duda, o desconfianza; pues quien anda dudando es semejante a la ola del mar alborotada y agitada de viento acá y allá.", ref: "Santiago 1:6" },
    { text: "Mas el que perseverare hasta el fin, ése se salvará.", ref: "Mateo 24:13" },
    { text: "No temas nada de lo que has de padecer. Mira que el diablo ha de meter a algunos de vosotros en la cárcel para que seáis tentados en la fe; y seréis atribulados por diez días. Sé fiel hasta la muerte, y te daré la corona de la vida eterna.", ref: "Apocalipsis 2:10" },
    { text: "He combatido con valor, he concluido la carrera, he guardado la fe.", ref: "2 Timoteo 4:7" },
    { text: "Ya que estamos, pues, rodeados de una tan grande nube de testigos, descargándonos de todo peso, y de los lazos del pecado que nos tiene ligados, corramos con aguante al término del combate, o la meta o hito, que nos es propuesto,", ref: "Hebreos 12:1" },
    { text: "poniendo siempre los ojos en Jesús, autor y consumador de la fe, el cual en vista del gozo que le estaba preparado en la gloria sufrió la cruz, sin hacer caso de la ignominia, y en premio está sentado a la diestra del trono de Dios.", ref: "Hebreos 12:2" },
    { text: "Resistidle firmes en la fe, sabiendo que la misma tribulación padecen vuestros hermanos, cuantos hay en el mundo.", ref: "1 Pedro 5:9" },
    { text: "Así que, amados hermanos míos, estad firmes y constantes, trabajando siempre más y más en la obra del Señor, que sabéis que vuestro trabajo no quedará sin recompensa delante del Señor.", ref: "1 Corintios 15:58" },
    { text: "Pero fiel es Dios, que os fortalecerá y defenderá del espíritu maligno.", ref: "2 Tesalonicenses 3:3" },
    { text: "No queráis, pues, malograr vuestra confianza, la cual recibirá un gran galardón.", ref: "Hebreos 10:35" },
    { text: "Porque os es necesaria la paciencia para que, haciendo la voluntad de Dios, obtengáis la promesa.", ref: "Hebreos 10:36" },
    { text: "Y no nos gloriamos solamente en esto, sino también en las tribulaciones, sabiendo que la tribulación ejercita la paciencia,", ref: "Romanos 5:3" },
    { text: "esperanza que no burla; porque la caridad de Dios ha sido derramada en nuestros corazones por medio del Espíritu Santo, que se nos ha dado.", ref: "Romanos 5:5" },
    { text: "Mediante vuestra paciencia salvaréis vuestras almas.", ref: "Lucas 21:19" },
    { text: "No todo aquel que me dice: ¡Oh, Señor, Señor! entrará por eso en el reino de los cielos; sino el que hace la voluntad de mi Padre celestial, ése es el que entrará en el reino de los cie-los.", ref: "Mateo 7:21" },
    { text: "Mas Jesús le respondió: Escrito está: No sólo de pan vive el hombre, sino de toda palabra o disposición que sale de la boca de Dios.", ref: "Mateo 4:4" },
    { text: "Bienaventurado, pues, aquel hombre que sufre con paciencia la tentación, o tribulación; porque después que fuere así probado, recibirá la corona de vida, que Dios ha prometido a los que le aman.", ref: "Santiago 1:12" },
    { text: "Perseverad en la oración, velando en ella y acompañándola con acciones de gracias,", ref: "Colosenses 4:2" },
    { text: "Porque no nos ha dado Dios a nosotros un espíritu de timidez, sino de fortaleza, y de caridad, y de templanza, y prudencia.", ref: "2 Timoteo 1:7" },
    { text: "Todo lo puedo en aquel que me conforta, esto es, en Cristo.", ref: "Filipenses 4:13" },
    { text: "El Señor es la fortaleza mía, y el objeto de mis alabanzas, porque El ha sido mi Salvador. Este es mi Dios, y yo publicaré su gloria: el Dios de mis padres, a quien he de ensalzar.", ref: "Éxodo 15:2" },
    { text: "Mas los que tienen puesta en el Señor su esperanza, adquirirán nuevas fuerzas, tomarán alas como de águila, correrán y no se fatigarán, andarán y no desfallecerán.", ref: "Isaías 40:31" },
    { text: "a fin de que sigáis una conducta digna de Dios agradándole en todo, produciendo frutos en toda especie de obras buenas, y adelantando en la ciencia de Dios,", ref: "Colosenses 1:10" },
    { text: "ir corriendo hacia el hito, para ganar el premio a que Dios llama desde lo alto por Jesucristo.", ref: "Filipenses 3:14" },
  ],
  10: [
    { text: "Pedid, y se os dará; ¡buscad, y hallaréis!: llamad, y os abrirán.", ref: "Mateo 7:7" },
    { text: "Orad sin intermisión.", ref: "1 Tesalonicenses 5:17" },
    { text: "Confesad, pues, vuestros pecados uno a otro, y orad los unos por los otros para que seáis salvos; porque mucho vale la oración perseverante del justo.", ref: "Santiago 5:16" },
    { text: "Y habiendo entrado el ángel a donde ella estaba, le dijo: Dios te salve, ¡oh llena de gracia!, el Señor es contigo; bendita tú eres entre todas las mujeres.", ref: "Lucas 1:28" },
    { text: "y exclamando en voz alta, dijo: ¡Bendita tú eres entre todas las mujeres, y bendito es el fruto de tu vientre!", ref: "Lucas 1:42" },
    { text: "Alegraos con la esperanza del premio", ref: "Romanos 12:12" },
    { text: "Velad y orad para no caer en la tentación. Que si bien el espíritu está pronto, la carne es flaca.", ref: "Mateo 26:41" },
    { text: "Tú, al contrario, cuando hubieres de orar, entra en tu aposento, y cerrada la puerta, ora en secreto a tu Padre, y tu Padre, que ve lo más secreto, te premiará en público.", ref: "Mateo 6:6" },
    { text: "Ved, pues, cómo habéis de orar: padre nuestro que estás en los cielos, santificado sea tu Nombre;", ref: "Mateo 6:9" },
    { text: "venga tu reino; hágase tu voluntad, así en la tierra, como en el cielo.", ref: "Mateo 6:10" },
    { text: "Danos hoy el pan nuestro de cada día", ref: "Mateo 6:11" },
    { text: "y perdónanos nuestras deudas así como nosotros perdonamos a nuestros deudores", ref: "Mateo 6:12" },
    { text: "y no nos dejes caer en la tentación", ref: "Mateo 6:13" },
    { text: "Y cuando pidiereis al Padre en mi nombre, yo lo haré, a fin de que el Padre sea glorificado en el Hijo.", ref: "Juan 14:13" },
    { text: "Entonces no habréis de preguntarme cosa alguna. En verdad, en verdad os digo, que cuanto pidiereis al Padre en mi nombre, os lo concederá.", ref: "Juan 16:23" },
    { text: "Porque el Espíritu Santo os enseñará en aquel trance lo que debéis decir.", ref: "Lucas 12:12" },
    { text: "Y además el espíritu divino ayuda a nuestra flaqueza; pues no sabiendo siquiera qué hemos de pedir en nuestras oraciones, ni cómo conviene hacerlo, el mismo espíritu hace, o produce en nuestro interior, nuestras peticiones a Dios con gemidos que son inexplicables.", ref: "Romanos 8:26" },
    { text: "Pero aquel que penetra a fondo los corazones conoce bien qué es lo que desea el Espíritu, el cual no pide nada por los santos, que no sea según Dios.", ref: "Romanos 8:27" },
    { text: "No os inquietéis por la solicitud de cosa alguna; mas en todo presentad a Dios vuestras peticiones por medio de la oración y de las plegarias, acompañadas de acción de gracias.", ref: "Filipenses 4:6" },
    { text: "Y la paz de Dios, que sobrepuja a todo entendimiento, sea la guardia de vuestros corazones y de vuestros sentimientos en Jesucristo.", ref: "Filipenses 4:7" },
    { text: "Perseverad en la oración, velando en ella y acompañándola con acciones de gracias,", ref: "Colosenses 4:2" },
    { text: "Quiero, pues, que los hombres oren en todo lugar, alzando las manos limpias, o puras de toda maldad, exentos de todo encono y disensión.", ref: "1 Timoteo 2:8" },
    { text: "Allegaos a Dios, y él se allegará a vosotros. Limpiad, ¡oh pecadores!, vuestras manos; y vosotros de ánimo doble, purificad vuestros corazones.", ref: "Santiago 4:8" },
    { text: "Huye del mal, y obra el bien; busca la paz, y empéñate en alcanzarla.", ref: "Salmos 33:14" },
    { text: "Desde lo más profundo clamé a ti, ¡oh Señor!", ref: "Salmos 129:1" },
    { text: "Ascienda mi oración ante tu acatamiento, como el olor del incienso; sea la elevación de mis manos tan grata, como el sacrificio de la tarde.", ref: "Salmos 140:2" },
    { text: "Como busca el sediente ciervo por las fuentes de aguas, así, ¡oh Dios!, clama por ti el alma mía.", ref: "Salmos 41:1" },
    { text: "Alabaré al Señor en todo tiempo, no cesarán mis labios de pronunciar sus alabanzas.", ref: "Salmos 33:1" },
    { text: "Siete veces al día te tributé alabanzas por los oráculos de tu justicia.", ref: "Salmos 118:164" },
    { text: "¡Dios mío, oh mi Dios!, a ti aspiro, y me dirijo desde que apunta la aurora. De ti está sedienta el alma mía. ¡Y de cuántas maneras lo está también este mi cuerpo!", ref: "Salmos 62:1" },
    { text: "Bueno es tributar alabanzas al Señor; y salmear a tu Nombre, ¡oh Altísimo!,", ref: "Salmos 91:1" },
  ],
  11: [
    { text: "Le dijo Jesús: Yo soy la resurrección y la vida: Quien cree en mí, aunque hubiere muerto, vivirá;", ref: "Juan 11:25" },
    { text: "De esta suerte, aunque caminase yo por la sombra de la muerte, no temeré ningún desastre; porque tú estás conmigo. Tu vara y tu báculo han sido mi consuelo.", ref: "Salmos 22:4" },
    { text: "En la casa de mi Padre hay muchas habitaciones; que si no fuese así, os lo hubiera yo dicho. Yo voy a preparar lugar para vosotros.", ref: "Juan 14:2" },
    { text: "Y cuando haya ido, y os haya preparado lugar, vendré otra vez, y os llevaré conmigo, para que donde yo estoy, estéis también vosotros.", ref: "Juan 14:3" },
    { text: "y de la cual está escrito: Ni ojo vio, ni oreja oyó, ni pasó a hombre por pensamiento cuáles cosas tiene Dios preparadas para aquellos que le aman.", ref: "1 Corintios 2:9" },
    { text: "Por lo cual estoy seguro de que ni la muerte, ni la vida, ni los ángeles, ni los principados, ni las virtudes, ni lo presente, ni lo venidero, ni la fuerza, o violencia,", ref: "Romanos 8:38" },
    { text: "Mas cuando este cuerpo mortal haya sido revestido de inmortalidad, entonces se cumplirá la palabra escrita: La muerte ha sido absorbida por una victoria.", ref: "1 Corintios 15:54" },
    { text: "Porque si creemos que Jesús, nuestra cabeza, murió y resucitó, también debemos creer que Dios resucitará y llevará con Jesús a la gloria a los que hayan muerto en la fe y amor de Jesús.", ref: "1 Tesalonicenses 4:14" },
    { text: "Después, nosotros los vivos, los que hayamos quedado, seremos arrebatados con ellos sobre nubes al encuentro de Cristo en el aire, y así estaremos con el Señor eternamente.", ref: "1 Tesalonicenses 4:17" },
    { text: "Y Dios enjugará de sus ojos todas las lágrimas; y no habrá ya muerte, ni llanto, ni alarido, ni habrá más dolor, porque las cosas de antes son pasadas.", ref: "Apocalipsis 21:4" },
    { text: "Y oí una voz del cielo que me decía: Escribe: Bienaventurados los muertos, que mueren en el Señor. Ya desde ahora, dice el Espíritu, que descansen de sus trabajos, puesto que sus obras los van acompañando.", ref: "Apocalipsis 14:13" },
    { text: "Las almas de los justos están en la mano de Dios", ref: "Sabiduría 3:1" },
    { text: "y como un aniquilamiento su partida de entre nosotros; mas ellos, a la verdad, reposan en paz.", ref: "Sabiduría 3:3" },
    { text: "Y si delante de los hombres han padecido tormentos, su esperanza está llena o segura de la feliz inmortalidad.", ref: "Sabiduría 3:4" },
    { text: "Al contrario, los justos vivirán eternamente, y su galardón está en el Señor, y el Altísimo tiene cuidado de ellos.", ref: "Sabiduría 5:16" },
    { text: "Pero nosotros vivimos ya como ciudadanos del cielo, de donde así mismo estamos aguardando al salvador Jesucristo Señor nuestro,", ref: "Filipenses 3:20" },
    { text: "A la verdad yo estoy firmemente persuadido de que los sufrimientos o penas de la vida presente no son de comparar con aquella gloria venidera, que se ha de manifestar en nosotros.", ref: "Romanos 8:18" },
    { text: "Ahora no vemos a Dios sino como en un espejo, y bajo imágenes oscuras; pero entonces le veremos cara a cara. Yo no le conozco ahora sino imperfectamente; mas entonces le conoceré con una visión clara, a la manera que soy yo conocido.", ref: "1 Corintios 13:12" },
    { text: "por cuanto el mismo Señor a la orden del arcángel, y al sonido de la trompeta de Dios, descenderá del cielo; y los que murieron en Cristo, resucitarán los primeros.", ref: "1 Tesalonicenses 4:16" },
    { text: "De gran precio es a los ojos del Señor la muerte de sus santos.", ref: "Salmos 115:6" },
    { text: "La memoria de los justos será celebrada", ref: "Proverbios 10:7" },
    { text: "Pero yo compareceré en tu presencia con la justicia de mis obras; y quedaré plenamente saciado, cuando se me manifieste tu gloria.", ref: "Salmos 16:15" },
    { text: "Porque yo sé que vive mi redentor, y que yo he de resucitar del polvo de la tierra en el último día,", ref: "Job 19:25" },
    { text: "Porque es necesario que este cuerpo corruptible sea revestido de incorruptibilidad, y que este cuerpo mortal sea revestido de inmortalidad.", ref: "1 Corintios 15:53" },
    { text: "¿Dónde está, ¡oh muerte!, tu victoria? ¿Dónde está, ¡oh muerte!, tu aguijón?", ref: "1 Corintios 15:55" },
    { text: "Pero demos gracias a Dios, que nos ha dado victoria contra la muerte y el pecado, por virtud de nuestro Señor Jesucristo.", ref: "1 Corintios 15:57" },
    { text: "Que como somos de Dios, si vivimos, para el Señor vivimos, y si morimos para el Señor morimos. Ora, pues, vivamos, ora muramos, del Señor somos.", ref: "Romanos 14:8" },
    { text: "Muchas son las tribulaciones de los justos De todos los huesos de ellos tiene el Señor sumo cuidado", ref: "Salmos 33:19-20" },
    { text: "Y abismará la muerte para siempre, y el Señor Dios enjugará las lágrimas de todos los rostros, y borrará de toda la tierra el oprobio de su pueblo, porque así lo ha pronunciado el Señor.", ref: "Isaías 25:8" },
    { text: "Aquellos que sembraban con lágrimas segarán llenos de júbilo.", ref: "Salmos 125:5" },
  ],
  12: [
    { text: "Este es aquel de quien se dijo por el profeta Isaías: Es la voz del que clama en el desierto, diciendo: Preparad el camino del Señor. Haced derechas sus sendas.", ref: "Mateo 3:3" },
    { text: "Por tanto el mismo Señor os dará la señal: Sabed que una virgen concebirá y tendrá un hijo, y su nombre será Emmanuel, o Dios con nosotros.", ref: "Isaías 7:14" },
    { text: "El pueblo que andaba entre tinieblas vio una gran luz", ref: "Isaías 9:2" },
    { text: "Ahora que ha nacido un parvulito para nosotros, y se nos ha dado un hijo, el cual lleva sobre sus hombros el principado, o la divisa de rey, y tendrá por nombre el Admirable, el Consejero, Dios, el Fuerte, el Padre del siglo venidero, el Príncipe de paz.", ref: "Isaías 9:6" },
    { text: "Mirad que viene el tiempo, dice el Señor, en que yo haré nacer de David un vástago, un Descendiente justo, el cual reinará como rey, y será sabio, y gobernará la tierra con rectitud y justicia.", ref: "Jeremías 23:5" },
    { text: "Y saldrá un renuevo del tronco de Jesé, y de su raíz se elevará una flor.", ref: "Isaías 11:1" },
    { text: "¡Oh cielos!, derramad desde arriba vuestro rocío; y lluevan las nubes al Justo, ábrase la tierra, y brote al Salvador, y nazca con él la justicia. Yo el Señor lo creé.", ref: "Isaías 45:8" },
    { text: "Les dijo entonces el ángel: No tenéis que temer; pues vengo a daros una nueva de grandísimo gozo para todo el pueblo,", ref: "Lucas 2:10" },
    { text: "y es, que hoy os ha nacido en la ciudad de David el Salvador, que es el Cristo, o Mesías, el Señor nuestro.", ref: "Lucas 2:11" },
    { text: "Gloria a Dios en lo más alto de los cielos, y paz en la tierra a los hombres de buena voluntad.", ref: "Lucas 2:14" },
    { text: "Y el Verbo se hizo carne; y habitó en medio de nosotros; y nosotros hemos visto su gloria, gloria que el Unigénito debía recibir del Padre, lleno de gracia y de verdad.", ref: "Juan 1:14" },
    { text: "En el mundo estaba, y el mundo fue por él hecho, y con todo el mundo no le conoció.", ref: "Juan 1:10" },
    { text: "Pero a todos los que le recibieron, que son los que creen en su nombre, les dio poder de llegar a ser hijos de Dios.", ref: "Juan 1:12" },
    { text: "Que amó tanto Dios al mundo, que no paró hasta dar a su hijo unigénito; a fin de que todos los que creen en él, no perezcan, sino que vivan vida eterna.", ref: "Juan 3:16" },
    { text: "Y tuvo a su hijo primogénito, y lo envolvió en pañales, y lo recostó en un pesebre, porque no hubo lugar para ellos en el mesón.", ref: "Lucas 2:7" },
    { text: "Vinieron, pues, a toda prisa, y hallaron a María y a José y al niño reclinado en el pesebre.", ref: "Lucas 2:16" },
    { text: "Al punto mismo se dejó ver con el ángel un ejército numeroso de la milicia celestial, alabando a Dios, y diciendo:", ref: "Lucas 2:13" },
    { text: "¡Levántate, oh Jerusalén !, recibe la luz; porque ha venido tu lumbrera y ha nacido sobre ti la gloria del Señor.", ref: "Isaías 60:1" },
    { text: "Conforme a lo que se halla escrito en el profeta Isaías: He aquí que despacho yo mi ángel o enviado ante tu presencia, el cual irá delante de ti preparándote el camino:", ref: "Marcos 1:2" },
    { text: "Yo soy, dijo entonces, la voz del que clama en el desierto: Enderezad el camino del Señor, como lo tiene dicho el profeta Isaías.", ref: "Juan 1:23" },
    { text: "Conviene que él crezca, y que yo mengüe.", ref: "Juan 3:30" },
    { text: "¿Eres tú el Mesías que ha de venir, o debemos esperar a otro?", ref: "Mateo 11:3" },
    { text: "El que da testimonio de estas cosas, dice: Ciertamente yo vengo luego. ¡Amén!. Ven, ¡oh Señor Jesús !", ref: "Apocalipsis 22:20" },
    { text: "He aquí que estoy a la puerta de tu corazón, y llamo; si alguno escuchare mi voz y me abriere la puerta, entraré a él, y con él cenaré, y él conmigo.", ref: "Apocalipsis 3:20" },
    { text: "Sea, pues, Dios loado por su don inefable.", ref: "2 Corintios 9:15" },
    { text: "Y tanto las gentes que iban delante, como las que venían detrás, clamaban diciendo: ¡Hosanna, al Hijo de David! ¡Bendito sea el que viene en nombre del Señor! ¡Hosanna en lo más alto de los cielos!", ref: "Mateo 21:9" },
    { text: "Al día siguiente vio Juan a Jesús que venía a encontrarle, y dijo: He aquí el cordero de Dios, ved aquí el que quita los pecados del mundo.", ref: "Juan 1:29" },
    { text: "Y él pidiendo la tablilla de escribir, escribió así: Juan es su nombre. Lo que llenó a todos de admiración.", ref: "Lucas 1:63" },
    { text: "Y tú, ¡oh niño!, tú serás llamado el profeta del Altísimo; porque irás delante del Señor a preparar sus caminos,", ref: "Lucas 1:76" },
    { text: "por las entrañas misericordiosas de nuestro Dios, que ha hecho que ese naciente haya venido a visitarnos de lo alto del cielo,", ref: "Lucas 1:78" },
    { text: "Ahora, Señor, ahora sí que sacas en paz de este mundo a tu siervo, según tu promesa.", ref: "Lucas 2:29" },
  ],
}

export function getDailyVerseEs() {
  const today = new Date()
  const verses = DAILY_VERSES_ES[today.getMonth() + 1]
  if (!verses) return null
  return verses[today.getDate() - 1] || null
}

export default DAILY_VERSES_ES
